// Observe-mode lists (coordinator guardrail 1). An A-class route is observe-allowed for an
// anonymous caller only where its Observe flag says so; every other A route refuses anonymous in
// every mode. "OK" below means ed.7's handler needed no caller identity (verified per route), so
// letting an un-proven session through only repeats ed.7's behaviour until enforcement.
var (
	// storyReportKinds are the POST /workspace/commands kinds that were claim-gated by their
	// sender in ed.7 and are observe-allowed (an assigned worker's evidence, review verdicts,
	// messages and questions). The authority kinds (done, assignment, ready_for_approval, answer,
	// answer_confirmation) and an empty-sender "board" action are not in the list.
	storyReportKinds = []string{"implementation", "testing", "installation", "release", "message", "handoff", "blocked", "unblocked", "review_passed", "review_failed", "question"}
	// spawnWorkerKinds are the POST /sessions kinds observe-allowed: a worker (the default). Spawning
	// an orchestrator is never anonymous.
	spawnWorkerKinds = []string{"", "worker"}
)

